    /**
     * Method to retrieve the Product via ProductFetchOneSummary
     * @param 	summary ProductFetchOneSummary 
     * @return 	ProductFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Product getProduct( ProductFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ProductFetchOneSummary arg cannot be null" );
    	
    	Product entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Product
        	// --------------------------------------
        	CompletableFuture<Product> futureEntity = queryGateway.query(new FindProductQuery( new LoadProductFilter( summary.getProductId() ) ), ResponseTypes.instanceOf(Product.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Product with id " + summary.getProductId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


    /**
     * Method to retrieve a collection of all Products
     *
     * @return 	List<Product> 
     * @exception ProcessingException Thrown if any problems
     */
    public List<Product> getAllProduct() 
    throws ProcessingException {
        List<Product> list = null;

        try {
        	CompletableFuture<List<Product>> futureList = queryGateway.query(new FindAllProductQuery(), ResponseTypes.multipleInstancesOf(Product.class));
        	
        	list = futureList.get();
        }
        catch( Exception exc ) {
            String errMsg = "Failed to get all Product";
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return list;
    }

